/* Pinned SDK; lazy loading keeps local planning available without network. */
(()=>{
let client,user=null,busy=false,loaded=false;const msg=s=>{$('#authMessage').textContent=s},status=s=>{$('#syncStatus').textContent=s};
const baselineKey=id=>'ritim-sync-'+id,cacheKey=id=>'ritim-user-'+id;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function store(key,value){localStorage.setItem(key,JSON.stringify(value))}
function ui(){ $('#signedIn').hidden=!user;$('#signedOut').hidden=!!user;$('#accountEmail').textContent=user?.email||'';$('#accountButton').textContent=user?'Hesabım':'Hesap' }
function switchUser(next){if(user?.id===next?.id)return;user=next;activeStorageKey=user?cacheKey(user.id):KEY;const cached=read(activeStorageKey,null);state=cached||freshState();save();render();if(user&&!cached){const seed={settings:{text:JSON.stringify(state.categories),stamp:null}};for(const [d,v] of Object.entries(state.days))seed[d]={text:JSON.stringify(v.entries),stamp:null};store(baselineKey(user.id),seed)}ui();status(user?'Hesap açık · Bulut kayıtlarını almak için Şimdi eşitle’ye dokun.':'Misafir modu · Kayıtlar yalnızca bu tarayıcıda.');}
async function init(){if(loaded)return;const {createClient}=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.105.0/+esm');client=createClient(window.RITIM_SUPABASE.url,window.RITIM_SUPABASE.key);const {data,error}=await client.auth.getSession();if(error)throw error;switchUser(data.session?.user||null);client.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>{if(!busy)switchUser(session?.user||null)},0)});loaded=true;ui()}
async function guard(fn){if(busy)return;busy=true;document.querySelectorAll('#accountDialog button').forEach(b=>b.disabled=true);document.querySelector('main').inert=true;try{await fn()}catch(e){msg(e.message||'Bağlantı kurulamadı. Yerel kayıtların korundu.');status('Eşitleme tamamlanmadı · Yerel kayıtlar korundu.')}finally{busy=false;document.querySelector('main').inert=false;document.querySelectorAll('#accountDialog button').forEach(b=>b.disabled=false)}}
async function sync(){if(!user)throw Error('Önce giriş yap.');const id=user.id,baseline=read(baselineKey(id),{}),local=structuredClone(state),rows={};msg('Bulut kayıtları kontrol ediliyor…');const settings=await client.from('planner_settings').select('categories,updated_at').eq('user_id',id).maybeSingle();if(settings.error)throw settings.error;if(settings.data)rows.settings={value:settings.data.categories,stamp:settings.data.updated_at};for(let from=0;;from+=500){const page=await client.from('planner_days').select('day,entries,updated_at').eq('user_id',id).order('day').range(from,from+499);if(page.error)throw page.error;for(const r of page.data)rows[r.day]={value:r.entries,stamp:r.updated_at};if(page.data.length<500)break}
const localRows={settings:local.categories,...Object.fromEntries(Object.entries(local.days).map(([d,v])=>[d,v.entries]))},keys=new Set([...Object.keys(rows),...Object.keys(localRows)]),plan=[];
for(const key of keys){const remote=rows[key],value=localRows[key],b=baseline[key],text=JSON.stringify(value),remoteText=JSON.stringify(remote?.value);const localDirty=(!remote&&value!==undefined)||(b?text!==b.text:value!==undefined&&key!=='settings');if(remote&&localDirty&&(!b||remote.stamp!==b.stamp)&&text!==remoteText)throw Error(`${key==='settings'?'Kategoriler':key} iki cihazda değişmiş. Önce yerel yedeğini al; veri kaybını önlemek için eşitleme durduruldu.`);plan.push({key,remote,value,write:localDirty&&text!==remoteText})}
for(const item of plan){let {key,remote,value,write}=item;let result=remote;if(write){const table=key==='settings'?'planner_settings':'planner_days',column=key==='settings'?'categories':'entries',payload={user_id:id,[column]:value,...(key==='settings'?{}:{day:key})};let q=remote?client.from(table).update({[column]:value}).eq('user_id',id).eq('updated_at',remote.stamp):client.from(table).insert(payload);if(remote&&key!=='settings')q=q.eq('day',key);const response=await q.select(column+',updated_at');if(response.error)throw response.error;if(response.data.length!==1)throw Error('Başka cihaz bu kaydı değiştirdi. Tekrar eşitlemeden önce yedek al.');result={value:response.data[0][column],stamp:response.data[0].updated_at}}
if(result){if(key==='settings')state.categories=result.value;else state.days[key]={entries:result.value};baseline[key]={text:JSON.stringify(result.value),stamp:result.stamp};store(baselineKey(id),baseline);save()}}
render();const when=new Date().toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'});msg('Kayıtlar eşitlendi.');status('Bulut eşitlendi · '+when+' · Sonraki değişiklikler için yeniden eşitle.');}
$('#accountButton').onclick=()=>{$('#accountDialog').showModal();guard(async()=>{await init();msg(user?'Hesabın hazır.':'Giriş yap veya hesap oluştur.')})};
$('#authForm').onsubmit=e=>{e.preventDefault();const f=e.target,action=e.submitter?.value||'login';guard(async()=>{await init();const payload={email:f.elements.email.value.trim(),password:f.elements.password.value};const response=action==='signup'?await client.auth.signUp({...payload,options:{emailRedirectTo:window.RITIM_SITE_URL}}):await client.auth.signInWithPassword(payload);if(response.error)throw response.error;f.elements.password.value='';if(response.data.session){switchUser(response.data.session.user);await sync()}else msg('Doğrulama e-postanı kontrol et. E-posta gönderimi yapılandırılmadıysa proje yöneticisiyle iletişime geç.')})};
$('#syncNow').onclick=()=>guard(sync);$('#signOut').onclick=()=>guard(async()=>{const {error}=await client.auth.signOut({scope:'local'});if(error)throw error;switchUser(null);msg('Çıkış yapıldı. Misafir planına döndün.')});
})();



